    private static void Check(bool value, string message) { if (!value) throw new InvalidOperationException(message); }
    public static async Task Run(string root, Func<string, Func<Task>, Task> test)
    {
        string executable = Environment.GetEnvironmentVariable("FLUXPLAYER_TEST_JELLYFIN") ?? Path.GetFullPath(Path.Combine(root, "../tools/jellyfin-12.4/jellyfin/jellyfin.exe")); if (!File.Exists(executable)) return;
        string folder = Path.Combine(root, "jellyfin-" + Guid.NewGuid().ToString("N")), address = "", user = "", token = "", movie = "", episode = "", music = Path.Combine(folder, "music"), films = Path.Combine(folder, "movies"), television = Path.Combine(folder, "television"); Process? backend = null; Task<string>? errors = null, output = null; PersonalMediaServer? source = null; ServerMediaRow[] audio = []; using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
        async Task<JsonElement> Request(string route, object? body = null)
        {
            using var request = new HttpRequestMessage(body == null ? HttpMethod.Get : HttpMethod.Post, address + route); if (body != null) request.Content = new StringContent(JsonSerializer.Serialize(body), Encoding.UTF8, "application/json"); using var response = await http.SendAsync(request); byte[] bytes = await response.Content.ReadAsByteArrayAsync(); Check(response.IsSuccessStatusCode, "Fixture Jellyfin " + route + " returned " + (int)response.StatusCode + ": " + Encoding.UTF8.GetString(bytes)[..Math.Min(bytes.Length, 1000)]); if (bytes.Length == 0) return JsonSerializer.SerializeToElement(new { }); using var json = JsonDocument.Parse(bytes); return json.RootElement.Clone();
        }
        Task<ServerActionRow[]> Action(string key, string id = "") => source!.ExecuteAction(key, id == "" ? new Dictionary<string, string>() : new Dictionary<string, string> { ["id"] = id }, CancellationToken.None);
        async Task Prepare()
        {
            if (source != null) return; foreach (string directory in new[] { music, films, television, Path.Combine(folder, "config") }) Directory.CreateDirectory(directory);
            Directory.CreateDirectory(Path.Combine(music, "Fixture Artist", "Fixture Album")); foreach (int n in new[] { 1, 2 }) await FfmpegJob.Run(["-loglevel", "error", "-f", "lavfi", "-i", "anullsrc=r=48000:cl=stereo:d=4", "-c:a", "flac", "-metadata", "title=Synthetic " + n, "-metadata", "artist=Fixture Artist", "-metadata", "album_artist=Fixture Artist", "-metadata", "album=Fixture Album", "-metadata", "date=2024", "-metadata", "genre=Fixture Genre", "-metadata", "track=" + n, Path.Combine(music, "Fixture Artist", "Fixture Album", "Track" + n + ".flac")], CancellationToken.None);
            string seed = Path.Combine(folder, "Seed.mkv"); await FfmpegJob.Run(["-loglevel", "error", "-f", "lavfi", "-i", "color=c=black:s=128x72:r=2:d=600", "-c:v", "libx264", "-preset", "ultrafast", seed], CancellationToken.None);
            foreach (int n in new[] { 1, 2 }) { string directory = Path.Combine(films, "Fixture Movie " + n + " (2024)"); Directory.CreateDirectory(directory); File.Copy(seed, Path.Combine(directory, "Fixture Movie " + n + " (2024).mkv")); await File.WriteAllTextAsync(Path.Combine(directory, "movie.nfo"), "<movie><title>Fixture Movie " + n + "</title><year>2024</year><genre>Fixture Genre</genre><studio>Fixture Studio</studio><tag>Fixture Tag</tag><plot>Local synthetic movie.</plot><lockdata>true</lockdata></movie>"); if (n == 1) { foreach (string extra in new[] { "trailers", "extras" }) { Directory.CreateDirectory(Path.Combine(directory, extra)); File.Copy(seed, Path.Combine(directory, extra, extra == "trailers" ? "Trailer.mkv" : "Feature.mkv")); } } }
            string show = Path.Combine(television, "Fixture Series"), season = Path.Combine(show, "Season 01"); Directory.CreateDirectory(season); await File.WriteAllTextAsync(Path.Combine(show, "tvshow.nfo"), "<tvshow><title>Fixture Series</title><year>2024</year><genre>Fixture Genre</genre><lockdata>true</lockdata></tvshow>"); foreach (int n in new[] { 1, 2 }) { string name = "Fixture Series S01E0" + n; File.Copy(seed, Path.Combine(season, name + ".mkv")); await File.WriteAllTextAsync(Path.Combine(season, name + ".nfo"), "<episodedetails><title>Fixture Episode " + n + "</title><season>1</season><episode>" + n + "</episode><lockdata>true</lockdata></episodedetails>"); }
            var reservation = new TcpListener(IPAddress.Loopback, 0); reservation.Start(); int port = ((IPEndPoint)reservation.LocalEndpoint).Port; reservation.Stop(); address = $"http://127.0.0.1:{port}/";
            await File.WriteAllTextAsync(Path.Combine(folder, "config", "network.xml"), $"<NetworkConfiguration><InternalHttpPort>{port}</InternalHttpPort><PublicHttpPort>{port}</PublicHttpPort><EnableIPv6>false</EnableIPv6><EnableRemoteAccess>false</EnableRemoteAccess><AutoDiscovery>false</AutoDiscovery><LocalNetworkAddresses><string>127.0.0.1</string></LocalNetworkAddresses></NetworkConfiguration>");
            var start = new ProcessStartInfo(executable) { WorkingDirectory = folder, UseShellExecute = false, CreateNoWindow = true, RedirectStandardError = true, RedirectStandardOutput = true }; foreach (string arg in new[] { "--datadir", Path.Combine(folder, "data"), "--configdir", Path.Combine(folder, "config"), "--cachedir", Path.Combine(folder, "cache"), "--logdir", Path.Combine(folder, "logs"), "--ffmpeg", ConversionService.FindExecutable()!, "--nowebclient", "--nonetchange" }) start.ArgumentList.Add(arg); backend = Process.Start(start)!; errors = backend.StandardError.ReadToEndAsync(); output = backend.StandardOutput.ReadToEndAsync(); var clock = Stopwatch.StartNew();
            while (true) { try { using var ping = await http.GetAsync(address + "Startup/Configuration"); if (ping.IsSuccessStatusCode) break; } catch (HttpRequestException) { } if (backend.HasExited || clock.Elapsed.TotalSeconds > 30) throw new IOException("Isolated Jellyfin failed startup: " + (backend.HasExited ? await errors + await output : "timeout")); await Task.Delay(100); }
            await Request("Startup/User"); await Request("Startup/User", new { Name = "fixture", Password = "Fixture-password-2026" }); await Request("Startup/Complete", new { }); http.DefaultRequestHeaders.TryAddWithoutValidation("Authorization", "MediaBrowser Client=\"FluxPlayerFixture\", Device=\"Windows\", DeviceId=\"" + Guid.NewGuid().ToString("N") + "\", Version=\"1.4.0\""); var login = await Request("Users/AuthenticateByName", new { Username = "fixture", Pw = "Fixture-password-2026" }); user = login.GetProperty("User").GetProperty("Id").GetString()!; token = login.GetProperty("AccessToken").GetString()!; string clientHeader = http.DefaultRequestHeaders.GetValues("Authorization").Single(); http.DefaultRequestHeaders.Remove("Authorization"); http.DefaultRequestHeaders.TryAddWithoutValidation("Authorization", clientHeader + ", Token=\"" + token + "\"");
            foreach (var library in new[] { (Name: "Fixture Music", Type: "music", Path: music), (Name: "Fixture Movies", Type: "movies", Path: films), (Name: "Fixture Television", Type: "tvshows", Path: television) }) await Request("Library/VirtualFolders?name=" + Uri.EscapeDataString(library.Name) + "&collectionType=" + library.Type + "&refreshLibrary=false", new { LibraryOptions = new { PathInfos = new[] { new { library.Path } }, EnableInternetProviders = false, EnableRealtimeMonitor = false, SaveLocalMetadata = false, EnableChapterImageExtraction = false, EnableTrickplayImageExtraction = false, TypeOptions = new[] { "Movie", "Series", "Season", "Episode", "MusicArtist", "MusicAlbum", "Audio" }.Select(type => new { Type = type, MetadataFetchers = Array.Empty<string>(), ImageFetchers = Array.Empty<string>() }).ToArray() } });
            await Request("Library/Refresh", new { }); clock.Restart(); JsonElement all;
            while (true) { all = await Request("Items?UserId=" + user + "&Recursive=true&IncludeItemTypes=Movie,Episode,Audio&Fields=MediaSources&Limit=100"); if (all.GetProperty("Items").GetArrayLength() >= 6) break; if (clock.Elapsed.TotalSeconds > 45) throw new IOException("Fixture Jellyfin did not index local music/movie/episode media: " + all); await Task.Delay(250); }
            var items = all.GetProperty("Items").EnumerateArray().ToArray();
            movie = items.First(i => i.GetProperty("Name").GetString()!.StartsWith("Fixture Movie 1", StringComparison.OrdinalIgnoreCase)).GetProperty("Id").GetString()!; episode = items.First(i => i.GetProperty("Name").GetString()!.StartsWith("Fixture Episode 1", StringComparison.OrdinalIgnoreCase)).GetProperty("Id").GetString()!;
            source = new(PersonalServerKind.Jellyfin, address, user, token); await source.Connect(CancellationToken.None); audio = (await source.Browse("Search", "", "Synthetic", CancellationToken.None)).Where(r => r.Kind == "Audio").ToArray(); Check(audio.Length == 2, "Fixture music is available to the selected user."); await Action("favorite", movie); await Action("played", episode); await Request("Sessions/Playing", new { ItemId = movie, PositionTicks = 0L, CanSeek = true, PlayMethod = "DirectPlay" }); await Request("Sessions/Playing/Stopped", new { ItemId = movie, PositionTicks = 1000000000L });
        }
        try
        {
            foreach (int id in Enumerable.Range(381, 10).Concat(Enumerable.Range(611, 20))) await test($"F{id:0000} Jellyfin native acceptance: real isolated server with local media", async () =>
            {
                await Prepare(); var active = source!;
                switch (id)
                {
                    case 381: await active.Connect(CancellationToken.None); using (var denied = new PersonalMediaServer(PersonalServerKind.Jellyfin, address, user, "incorrect")) { bool refused = false; try { await denied.Connect(CancellationToken.None); } catch (IOException) { refused = true; } Check(refused, "Invalid session tokens are rejected."); } break;
                    case 382: var roots = await active.Browse("Roots", "", "", CancellationToken.None); Check(roots.Length == 3, "Three explicit library roots."); Check((await active.Browse("Children", roots.Single(r => r.Title == "Fixture Movies").Id, "", CancellationToken.None)).Count(r => r.Kind == "Movie") == 2, "Selected collection navigation."); break;
                    case 383: Check((await active.Browse("Movies", "", "", CancellationToken.None)).Length == 2, "Bounded real movie browsing."); break;
                    case 384: var series = (await active.Browse("Series", "", "", CancellationToken.None)).Single(); var seasons = await active.Browse("Children", series.Id, "", CancellationToken.None); Check(seasons.Any(r => r.Kind == "Season"), "Series exposes season navigation."); Check((await active.Browse("Children", seasons.Single(r => r.Kind == "Season").Id, "", CancellationToken.None)).Count(r => r.Kind == "Episode") == 2, "Season exposes both indexed episodes."); break;
                    case 385: var album = (await active.Browse("Music", "", "", CancellationToken.None)).Single(); Check((await active.Browse("Children", album.Id, "", CancellationToken.None)).Count(r => r.Kind == "Audio") == 2, "Music album and audio track navigation."); break;
                    case 386: Check((await active.Browse("Search", "", "Fixture Movie 2", CancellationToken.None)).Any(r => r.Title == "Fixture Movie 2"), "Search uses actual backend title metadata."); break;
                    case 387: Check((await active.Browse("Resume", "", "", CancellationToken.None)).Any(r => r.Id == movie), "Playback report produces a real resumable item."); break;
                    case 388: Check((await active.Browse("Favorites", "", "", CancellationToken.None)).Any(r => r.Id == movie), "Read-only favorite view reflects server state."); break;
                    case 389:
                        await using (var relay = new RemoteMediaRelay()) { string url = relay.Register((range, cancellation) => active.Stream(audio[0], range, false, cancellation)); using var engine = new MediaService(hardwareDecoding: false, enableDiagnosticLogging: false); engine.SetVolume(0); engine.PlayFile(url); var clock = Stopwatch.StartNew(); while (!engine.IsPlaying || engine.GetTime() < 200) { if (clock.Elapsed.TotalSeconds > 6) throw new IOException("Authenticated Jellyfin relay did not play actual audio."); await Task.Delay(30); } engine.Stop(); } break;
                    case 390: string downloaded = Path.Combine(folder, "Downloaded.flac"); await active.Download(audio[0], downloaded, CancellationToken.None); Check((await File.ReadAllBytesAsync(downloaded)).SequenceEqual(await File.ReadAllBytesAsync(Path.Combine(music, "Fixture Artist", "Fixture Album", audio[0].Title.EndsWith('1') ? "Track1.flac" : "Track2.flac"))), "Original download retains bytes."); break;
                    default:
                        var definition = ServerActionCatalog.Personal[id - 611]; string key = definition.Key; var input = definition.Fields.ToDictionary(f => f.Key, f => f.Key switch { "id" => movie, "name" => "Fixture Playlist ñ", "items" => audio[0].Id + "\n" + audio[1].Id, _ => f.Default }); var rows = await active.ExecuteAction(key, input, CancellationToken.None);
                        if (!definition.Writes) Check(rows.Length > 0, "Real server returns positive fixture data for " + key + ".");
                        if (key is "favorite" or "unfavorite" or "played" or "unplayed" or "like" or "rating-clear") { var details = await Request("Items/" + movie + "?UserId=" + user); var state = details.GetProperty("UserData"); if (key is "favorite" or "unfavorite") Check(state.GetProperty("IsFavorite").GetBoolean() == (key == "favorite"), "Favorite mutation is visible in independent server response."); if (key is "played" or "unplayed") Check(state.GetProperty("Played").GetBoolean() == (key == "played"), "Played-state mutation is visible at server."); if (key == "like") Check(state.GetProperty("Likes").GetBoolean(), "Personal like is visible at server."); if (key == "rating-clear") Check(!state.TryGetProperty("Likes", out var likes) || likes.ValueKind == JsonValueKind.Null, "Personal rating clears at server."); }
                        if (key == "playlist-create") { string created = rows.Single().Id; Check(Guid.TryParse(created, out _), "Created playlist has a server UUID."); var entries = await Request("Playlists/" + created + "/Items?UserId=" + user); Check(entries.GetProperty("Items").EnumerateArray().Select(i => i.GetProperty("Id").GetString()).SequenceEqual(audio.Select(r => r.Id)), "Created user-owned playlist preserves selected track order."); }
                        break;
                }
            });
        }
        finally { source?.Dispose(); if (backend != null) { if (!backend.HasExited) backend.Kill(true); await backend.WaitForExitAsync(); if (errors != null && output != null) await File.WriteAllTextAsync(Path.Combine(folder, "backend-console.log"), await errors + await output); backend.Dispose(); } }
    }
